import Foundation

extension LegalGuides {
    static let interpreting = DirectoryGuide(
        cardSummary: .init(ukrainian: "Усний переклад на прийомі та засвідчений переклад документів", german: "Dolmetschen beim Termin und beglaubigte Dokumente"),
        introduction: .init(ukrainian: "Усний переклад, письмовий переклад і засвідчення — різні послуги. Спершу уточніть вимогу того органу, який прийматиме документ чи проводитиме розмову.", german: "Dolmetschen, schriftliche Übersetzung und Beglaubigung sind unterschiedliche Leistungen. Zuerst die Anforderungen der empfangenden Stelle klären."),
        sections: [
            .init("oral", "person.2", "Перед прийомом попросіть усного перекладача", "Vor dem Termin Dolmetschung klären", "Повідомте установі мову й діалект, дату прийому та потребу в усному перекладі. Запитайте, чи запрошує перекладача сама установа, чи дозволена ваша довірена особа, хто оплачує послугу й чи потрібно змінити час. У суді, поліції та процедурах притулку правила відрізняються — не наймайте приватного фахівця, доки не отримаєте відповідь.", "Sprache und Dialekt, Termin und Dolmetschbedarf früh mitteilen. Fragen, ob die Stelle eine Fachperson organisiert, eine Vertrauensperson zulässt, wer zahlt und ob der Termin verlegt werden muss. Gericht, Polizei und Asylverfahren haben unterschiedliche Regeln – erst nach Klärung privat beauftragen.", source: interpreters),
            .init("written", "doc.text", "Що саме потрібно перекласти", "Welche Unterlagen übersetzt werden müssen", "Попросіть установу письмово вказати потрібні документи, сторінки, мову, чи потрібен оригінал, апостиль і засвідчений переклад. Одна установа може прийняти копію, інша — вимагати оригінал із перекладом. Не замовляйте весь пакет до уточнення; правила апостиля описані окремо в темі «Документи».", "Empfangende Stelle schriftlich nach Dokumenten, Seiten, Sprache, Original, Apostille und beglaubigter Übersetzung fragen. Eine Stelle akzeptiert eine Kopie, eine andere verlangt Original samt Übersetzung. Nicht die ganze Akte vorab übersetzen lassen; Apostille ist im Thema „Dokumente“ erklärt.", source: interpreters),
            .init("find", "magnifyingglass", "Перевірте фахівця в реєстрі Justiz", "Fachperson in der Justizliste finden", "В офіційному реєстрі виберіть українську чи іншу потрібну мову та судовий округ або всю Австрію. Звірте актуальні контакти й запитайте, чи фахівець виконує саме потрібний усний або письмовий переклад. Заздалегідь надішліть вимоги установи, але обережно поводьтеся з чутливими документами.", "In der amtlichen Liste Ukrainisch oder die benötigte Sprache und Gerichtsbezirk oder ganz Österreich auswählen. Aktuelle Kontaktdaten prüfen und fragen, ob genau die erforderliche mündliche oder schriftliche Leistung angeboten wird. Anforderungen der Stelle vorab senden, sensible Dokumente dabei bewusst schützen.", source: interpreters),
            .init("quote", "eurosign.circle", "Погодьте ціну та видачу", "Preis und Lieferung vereinbaren", "Попросіть письмову ціну з урахуванням сторінок, терміновості, засвідчення, доставки й додаткових примірників. Уточніть, чи приймуть електронну форму, чи потрібен паперовий оригінал. Збережіть замовлення, рахунок і готовий переклад; перевірте написання імені та дат до подання.", "Schriftliches Angebot inklusive Seiten, Eilzuschlag, Beglaubigung, Zustellung und Zusatzexemplaren einholen. Klären, ob eine elektronische Fassung genügt oder ein Papieroriginal nötig ist. Auftrag, Rechnung und Übersetzung sichern; Namen und Daten vor Einreichung prüfen.", source: interpreters),
            .init("meeting", "text.bubble", "Як діяти, якщо переклад на прийомі неточний", "Wenn beim Termin falsch gedolmetscht wird", "Попросіть повторити запитання повільніше й одразу повідомте про помилку перекладу. Перед підписом протоколу попросіть зачитати або перекласти важливі твердження та внести виправлення. Якщо зміст рішення чи протоколу все ще незрозумілий, попросіть копію й негайно зверніться по правову допомогу, особливо коли вже йде строк скарги.", "Um langsamere Wiederholung bitten und Dolmetschfehler sofort ansprechen. Vor Unterschrift wichtige Aussagen im Protokoll vorlesen oder übersetzen und berichtigen lassen. Bleibt Inhalt von Entscheidung oder Protokoll unklar, Kopie verlangen und bei laufender Rechtsmittelfrist unverzüglich Rechtsberatung suchen.", source: interpreters)
        ], sources: [interpreters]
    )
